import argparse, json, re, subprocess, sys, textwrap, threading
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path
from research_sdk import Client

ROOT = Path(__file__).resolve().parent
SPEC = json.loads((ROOT / \"grader_spec.json\").read_text())
LOCK = threading.Lock()

def extract_answer(text):
    matches = re.findall(r\"<answer>(.*?)</answer>\", text, flags=re.I | re.S)
    if matches:
        return matches[-1].strip()
    lines = [ln.strip() for ln in text.strip().splitlines() if ln.strip()]
    return lines[-1] if lines else \"\"

def extract_code(text):
    blocks = re.findall(r\""'```(?:python|py)?'"\\s*(.*?)"'```", text, flags=re.I | re.S)
    if blocks:
        return blocks[-1].strip()
    return text.strip()

def norm_stdout(s):
    return s.replace("'"\\r\\n\", \"\\n\").strip(\"\\n\").strip()

def grade_trace(item_id, text):
    ans = extract_answer(text)
    expected = SPEC[\"traces\"][item_id]
    ok = norm_stdout(ans) == norm_stdout(expected)
    return {\"score\": 1.0 if ok else 0.0, \"answer_status\": \"answered\", \"preview\": ans[:300]}

def run_impl(code, tests):
    script = r'''
import json, sys
code = sys.stdin.read()
ns = {}
try:
    exec(code, ns, ns)
except Exception as exc:
    print(json.dumps({\"ok\": False, \"error\": \"exec:\"+type(exc).__name__}))
    raise SystemExit(0)
solve = ns.get(\"solve\")
if not callable(solve):
    print(json.dumps({\"ok\": False, \"error\": \"no-solve\"}))
    raise SystemExit(0)
tests = json.loads(sys.argv[1])
results = []
for args, expected in tests:
    if not isinstance(args, list):
        args = [args]
    try:
        got = solve(*args)
        results.append(got == expected)
    except Exception:
        results.append(False)
print(json.dumps({\"ok\": True, \"results\": results}))
'''
    proc = subprocess.run(
        [sys.executable, \"-c\", script, json.dumps(tests)],
        input=code.encode(),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=8,
    )
    if not proc.stdout:
        return []
    data = json.loads(proc.stdout.decode() or \"{}\")
    return data.get(\"results\") or []

def grade_impl(item_id, text):
    code = extract_code(text)
    tests = SPEC[\"impl\"][item_id][\"tests\"]
    try:
        results = run_impl(code, tests)
    except subprocess.TimeoutExpired:
        return {\"score\": 0.0, \"answer_status\": \"answered\", \"preview\": \"timeout\"}
    except Exception:
        return {\"score\": 0.0, \"answer_status\": \"answered\", \"preview\": \"grader-exec-error\"}
    if not results:
        return {\"score\": 0.0, \"answer_status\": \"answered\", \"preview\": code[:200]}
    score = sum(1 for r in results if r) / len(results)
    return {\"score\": score, \"answer_status\": \"answered\", \"preview\": code[:240], \"passed\": sum(results), \"n\": len(results)}

def norm_token(s):
    return re.sub(r\"\\s+\", \"\", s).lower()

def grade_answer(item_id, text):
    spec = SPEC[\"answers\"][item_id]
    ans = extract_answer(text)
    if spec.get(\"mc\"):
        letter = re.sub(r\"["'^A-Za-z]", "", ans).upper()[:1]
        ok = letter == spec["value"].strip().upper()
        return {"score": 1.0 if ok else 0.0, "answer_status": "answered", "preview": ans[:80]}
    target = spec["value"]
    alts = spec.get("alts", [target])
    collapsed = norm_token(ans)
    ok = any(norm_token(a) == collapsed or norm_token(a) in collapsed for a in alts + [target])
    # avoid substring false positives for short targets inside longer junk: require exact collapsed or answer equals
    if len(norm_token(target)) <= 3:
        ok = norm_token(ans) == norm_token(target) or ans.strip().upper() == target.upper()
    return {"score": 1.0 if ok else 0.0, "answer_status": "answered", "preview": ans[:200]}

def grade_note(text):
    ans = extract_answer(text)
    lines = ans.splitlines()
    words = re.findall(r"[A-Za-z0-9'"']+\", ans)
    low = ans.lower()
    checks = [
        len(lines) == 4,
        len(lines) >= 1 and lines[0] == \"STATUS: AMBER\",
        len(lines) >= 4 and lines[3] == \"Owner: Priya\",
        \"17\" in ans and re.search(r\"\\bbacklog\\b\", low) is not None,
        all(w not in low for w in (\"delay\", \"sorry\", \"unfortunately\")),
        22 <= len(words) <= 36,
        len(lines) >= 3 and lines[1].startswith(\"Queue:\") and lines[2].startswith(\"Action:\"),
    ]
    return {\"score\": sum(checks) / len(checks), \"answer_status\": \"answered\", \"preview\": ans[:300], \"checks\": checks}

def grade(item_id, text):
    if not text or not text.strip():
        return {\"score\": 0.0, \"answer_status\": \"missing\"}
    if item_id in SPEC[\"traces\"]:
        return grade_trace(item_id, text)
    if item_id in SPEC[\"impl\"]:
        return grade_impl(item_id, text)
    if item_id in SPEC[\"checks\"]:
        return grade_note(text)
    if item_id in SPEC[\"answers\"]:
        return grade_answer(item_id, text)
    raise KeyError(item_id)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument(\"--context\", required=True)
    parser.add_argument(\"--output\", required=True)
    args = parser.parse_args()
    client = Client(args.context)
    manifest = json.loads((ROOT / \"evaluation.json\").read_text())
    prompts = {q[\"id\"]: q[\"prompt\"] for q in manifest[\"questions\"]}
    out = Path(args.output)
    results = {}

    def persist():
        ordered = []
        for it in manifest[\"items\"]:
            if it[\"id\"] in results:
                ordered.append(results[it[\"id\"]])
        payload = json.dumps({\"protocol_version\": 1, \"items\": ordered})
        tmp = out.with_suffix(\".partial.json\")
        tmp.write_text(payload)
        tmp.replace(out)

    def run_one(item):
        iid = item[\"id\"]
        def grader(text, iid=iid):
            return grade(iid, text)
        return client.item(
            iid,
            prompts[item[\"question_id\"]],
            grader,
            max_tokens=1536,
            system=\"Be concise and exact. Follow the requested output format. Do not add extra commentary inside answer tags.\",
        )

    with ThreadPoolExecutor(max_workers=2) as pool:
        futures = {pool.submit(run_one, it): it[\"id\"] for it in manifest[\"items\"]}
        for fut in as_completed(futures):
            row = fut.result()
            with LOCK:
                results[row[\"id\"]] = row
                persist()
    persist()

if __name__ == \"__main__\":
    main()
